    17	/**
    18	 * Perform a queued post request
    19	 */
    20	function post(command: string, data: Record<string, unknown> = {}, type = CONST.NETWORK.METHOD.POST, shouldUseSecure = false): Promise<Response> {
    21	    return new Promise((resolve, reject) => {
    22	        const request: Request = {
    23	            command,
    24	            data,
    25	            type,
    26	            shouldUseSecure,
    27	        };
    28	
    29	        // By default, request are retry-able and cancellable
    30	        // (e.g. any requests currently happening when the user logs out are cancelled)
    31	        request.data = {
    32	            ...data,
    33	            shouldRetry: data?.shouldRetry ?? true,
    34	            canCancel: data?.canCancel ?? true,
    35	            appversion: pkg.version,
    36	        };
    37	
    38	        // Add promise handlers to any request that we are not persisting
    39	        request.resolve = resolve;
    40	        request.reject = reject;
    41	
    42	        // Add the request to a queue of actions to perform
    43	        MainQueue.push(request);
    44	
    45	        // This check is mainly used to prevent API commands from triggering calls to MainQueue.process() from inside the context of a previous
    46	        // call to MainQueue.process() e.g. calling a Log command without this would cause the requests in mainQueue to double process
    47	        // since we call Log inside MainQueue.process().
    48	        const shouldProcessImmediately = request?.data?.shouldProcessImmediately ?? true;
    49	        if (!shouldProcessImmediately) {
    50	            return;
    51	        }
    52	
    53	        // Try to fire off the request as soon as it's queued so we don't add a delay to every queued command
    54	        MainQueue.process();
    55	    });
